'EPIC-025'; from datetime import date; from decimal import Decimal; import pytest; pytestmark = [pytest.mark.integration, pytest.mark.e2e]; TEST_DATE = date(2024, 6, 15)
async def _create_account(client, name, acct_type, currency='SGD'): resp = await client.post('/accounts', json={'name': name, 'type': acct_type, 'currency': currency}); assert resp.status_code == 201, resp.text; return resp.json()['id']
async def _post_balanced_entry(client, *, debit_id, credit_id, amount, currency='SGD'): create = await client.post('/journal-entries', json={'entry_date': TEST_DATE.isoformat(), 'memo': 'EPIC-025 opening balance', 'lines': [{'account_id': debit_id, 'direction': 'DEBIT', 'amount': amount, 'currency': currency}, {'account_id': credit_id, 'direction': 'CREDIT', 'amount': amount, 'currency': currency}]}); assert create.status_code == 201, create.text; entry_id = create.json()['id']; posted = await client.post(f'/journal-entries/{entry_id}/postings'); assert posted.status_code == 200, posted.text; return entry_id
@pytest.mark.e2e
async def test_epic025_reporting_calc_extraction_preserves_balance_sheet(client, test_user): 'AC25.1.1 EPIC-025'; bank_id = await _create_account(client, 'Bank', 'ASSET'); equity_id = await _create_account(client, 'Opening Equity', 'EQUITY'); await _post_balanced_entry(client, debit_id=bank_id, credit_id=equity_id, amount='1000.00'); resp = await client.get('/reports/balance-sheet'); assert resp.status_code == 200, resp.text; data = resp.json(); assert Decimal(str(data['total_assets'])) == Decimal('1000.00'); assert Decimal(str(data['total_liabilities'])) == Decimal('0.00'); assert Decimal(str(data['total_equity'])) == Decimal('1000.00'); assert Decimal(str(data['equation_delta'])) == Decimal('0.00'); assert data['is_balanced'] is True
